    obstacles = observation.get('obstacles', [])
    attack_mode = observation.get('attack_mode', False)

    def move_towards(tx, ty):
        dx, dy = 0, 0
        if tx > px:
            dx = 1
        elif tx < px:
            dx = -1
        if ty > py:
            dy = 1
        elif ty < py:
            dy = -1
        return dx, dy

    def is_blocked(nx, ny):
        if nx < 0 or nx >= gw or ny < 0 or ny >= gh:
            return True
        if (nx, ny) in obstacles:
            return True
        return False

