    def approach_opponent():
        dx, dy = move_towards(ox, oy)
        nx, ny = px + dx, py + dy
        if not is_blocked(nx, ny):
            return [dx, dy]
        # try alternatives
        for ddx, ddy in [(-1,0),(1,0),(0,-1),(0,1)]:
            nnx, nny = px + ddx, py + ddy
            if not is_blocked(nnx, nny):
