                nnx, nny = px + ddx, py + ddy
                if not is_blocked(nnx, nny):
                    return [ddx, ddy]
        return [0, 0]

    # If resources available, approach them
    if resources:
        return approach_resource()

    # Else, approach opponent defensively
    return approach_opponent()

